            border: 1px solid black;
        }
    </style>
</head>
<body>
    <canvas id="pendulum-canvas" width="500" height="500"></canvas>
    <input id="angle-input" type="number" value="45" />
    <button id="release-button">Release Pendulum</button>
    <script>
        let canvas = document.getElementById('pendulum-canvas');
        let ctx = canvas.getContext('2d');
        let pendulum = {
            x: canvas.width / 2,
            y: canvas.height / 2,
            angle: 0,
            length: 100,
            gravity: 0.1,
            velocity: 0,
            radius: 5
        };
        let updateInterval;

        function drawPendulum() {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            ctx.beginPath();
            ctx.arc(pendulum.x, pendulum.y, pendulum.radius, 0, 2 * Math.PI);
            ctx.fillStyle = 'black';
            ctx.fill();
            ctx.beginPath();
            ctx.moveTo(pendulum.x, pendulum.y - pendulum.length);
            ctx.lineTo(pendulum.x + pendulum.radius * Math.sin(pendulum.angle), pendulum.y - pendulum.length + pendulum.radius * Math.cos(pendulum.angle));
            ctx.stroke();
        }

        function updatePendulum() {
            pendulum.angle += pendulum.velocity;
            pendulum.velocity += pendulum.gravity * Math.sin(pendulum.angle);
            pendulum.velocity *= 0.99; // damping
            if (pendulum.velocity > 0.01) {
                pendulum.velocity = 0;
                pendulum.angle = 0;
            }
            drawPendulum();
        }

        function releasePendulum() {
            pendulum.angle = Number(document.getElementById('angle-input').value);
            pendulum.velocity = 0;
            updateInterval = setInterval(updatePendulum, 16);
        }

        drawPendulum();

        document.getElementById('release-button').addEventListener('click', releasePendulum);
    </script>
</body>
</html>
```

